DEST=ROOT/'external/channel-tools/WiiRoom-reference'
LOCK=ROOT/'configs/wiiroom-server-references.lock.json'


def fetch(row):
    p=DEST/row['path']
    if not p.resolve().is_relative_to(DEST.resolve()):raise ValueError('Reference path escape')
    if p.exists():raw=p.read_bytes()
    else:
        raw=urllib.request.urlopen('https://raw.githubusercontent.com/WiiLink24/room-server/'+COMMIT+'/'+row['path'],timeout=40).read(2*1024*1024)
        if len(raw)!=row['size']:raise ValueError('Public reference size')
        blob=hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()
        if blob!=row['git_blob_sha1']:raise ValueError('Public Git blob hash')
        p.parent.mkdir(parents=True,exist_ok=True)
        with p.open('xb')as f:f.write(raw)
    if len(raw)!=row['size']or hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()!=row['git_blob_sha1']:raise ValueError('Reference changed')
    return dict(**row,sha256=hashlib.sha256(raw).hexdigest())


def main():
    with concurrent.futures.ThreadPoolExecutor(max_workers=6)as pool:rows=list(pool.map(fetch,FILES))
    data=dict(schema=1,repository='https://github.com/WiiLink24/room-server',commit=COMMIT,files=rows)
    if LOCK.exists():
        if json.loads(LOCK.read_text(encoding='utf-8'))!=data:raise ValueError('Pinned reference differs')
    else:LOCK.write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(repository='WiiLink24/room-server',commit=COMMIT,unmodified_public_files=len(rows))))


if __name__=='__main__':main()

